\draw[black] (-0.14,705)--(0.14,735);
\draw[black] (-0.14,725)--(0.14,755);
\draw[dashed,black] (0,1100)--(12,1100);
\foreach \v in {800,1100,1400} {\draw[black] (-0.12,\v)--(0.12,\v);\path (0,\v) node[left,font=\fontsize{8.5}{10}\selectfont] {$\v$};}
\foreach \v in {6,12} {\draw[black] (\v,635)--(\v,665);\path (\v,650) node[below,font=\fontsize{8.5}{10}\selectfont] {$\v$};}
\draw[thick,modelblue,domain=0:12,samples=100] plot (\x,{1100+300*cos(30*\x)});
